questionvariables.text:
/* Design: find-the-mistake pattern (reading comprehension). Source: original. Wrong index 1 four times, 2 three, 3 three; errors dir 3, swap 2, strict 2, ratio 2, single 1. */
/* lincan(q): canonical form of a linear inequality in x and y: [strict?, [a, b, c]] meaning a*x + b*y + c (< or <=) 0 */
lincan(q) := block([r, d, s], r: op(q), d: expand(lhs(q) - rhs(q)),
    if r = ">" or r = ">=" then d: -d,
    s: is(r = "<" or r = ">"),
    [s, map(lambda([t], float(t)), [coeff(d, x), coeff(d, y), subst([x = 0, y = 0], d)])]);
lpar(u, v) := is(abs(u[1]*v[2] - u[2]*v[1]) + abs(u[1]*v[3] - u[3]*v[1]) + abs(u[2]*v[3] - u[3]*v[2]) < 1/10^9 * (abs(u[1]) + abs(u[2]) + abs(u[3])) * (abs(v[1]) + abs(v[2]) + abs(v[3])));
ldot(u, v) := u[1]*v[1] + u[2]*v[2] + u[3]*v[3];
/* lcls(L, T): "same" region; "dir" same boundary, other side, same strictness; "strict" same side, other strictness; "both"; "other" */
lcls(L, T) := block([l: lincan(L), t: lincan(T)],
    if not lpar(l[2], t[2]) then "other"
    elseif ldot(l[2], t[2]) > 0 then (if l[1] = t[1] then "same" else "strict")
    elseif l[1] = t[1] then "dir" else "both");
/* the validator: an inequality in x and y, linear */
validate_ineq(ex) := block([e: ev(ex, simp), d],
    if atom(e) or not member(op(e), ["<", "<=", ">", ">="]) then
        "Type an inequality using <, <=, > or >=, for example 2*x+3*y<=60. An equation with = is not an inequality."
    elseif listofvars(e) = [] or not every(lambda([v], member(v, [x, y])), listofvars(e)) then "Use only the letters x and y."
    else (d: ev(expand(lhs(e) - rhs(e)), simp),
          if not ev(polynomialp(d, [x, y]), simp) then
              "This inequality should be linear: only numbers times x and y, added or subtracted."
          elseif ev(hipow(d, x), simp) > 1 or ev(hipow(d, y), simp) > 1 or not freeof(x, ev(coeff(d, y), simp)) then
              "This inequality should be linear: no powers or products of x and y." else ""));
/* mkineq([a, b, rel, c]): the inequality a*x + b*y rel c */
mkineq(L) := if L[3] = "<=" then L[1]*x + L[2]*y <= L[4] elseif L[3] = "<" then L[1]*x + L[2]*y < L[4]
    elseif L[3] = ">=" then L[1]*x + L[2]*y >= L[4] else L[1]*x + L[2]*y > L[4];
Q13L: [["A school canteen in Embu sells \\(x\\) plates of githeri and \\(y\\) plates of pilau in a day.",["A plate of githeri costs Ksh \\(30\\) to make and a plate of pilau costs Ksh \\(70\\); the canteen has Ksh \\(6300\\).","At least \\(50\\) plates of pilau are sold.","The canteen sells more than \\(100\\) plates."],[30*x+70*y<=6300,1*y>=50,1*x+1*y>100],2,"dir",1*y<=50,["30x + 70y \\le 6300","y \\le 50","x + y \\gt 100"],["30x + 70y \\le 6300","y \\ge 50","x + y \\gt 100"],">="],
["A lorry owner in Nakuru plans \\(x\\) trips to Dar es Salaam and \\(y\\) trips to Mombasa in a month.",["A Dar es Salaam trip uses \\(900\\) litres of diesel and a Mombasa trip uses \\(700\\) litres; there are at most \\(9100\\) litres.","There are at least three times as many Dar es Salaam trips as Mombasa trips.","There are fewer than \\(15\\) trips in total."],[900*x+700*y<=9100,1*x-3*y>=0,1*x+1*y<15],1,"swap",700*x+900*y<=9100,["700x + 900y \\le 9100","x - 3y \\ge 0","x + y \\lt 15"],["900x + 700y \\le 9100","x - 3y \\ge 0","x + y \\lt 15"],"<="],
["A dairy cooperative in Ol Kalou sends \\(x\\) churns of milk to Nakuru and \\(y\\) churns to Nyahururu each day.",["The lorry carries at most \\(40\\) churns.","Nakuru takes more than \\(15\\) churns.","Nyahururu takes at least \\(8\\) churns."],[1*x+1*y<=40,1*x>15,1*y>=8],2,"strict",1*x>=15,["x + y \\le 40","x \\ge 15","y \\ge 8"],["x + y \\le 40","x \\gt 15","y \\ge 8"],">"],
["A youth group in Kisumu makes \\(x\\) desks and \\(y\\) chairs for a school.",["A desk uses \\(8\\) metres of timber and a chair uses \\(3\\) metres; there are \\(160\\) metres of timber.","There must be at least four times as many chairs as desks.","There must be at least \\(6\\) desks."],[8*x+3*y<=160,-4*x+1*y>=0,1*x>=6],2,"ratio",-1*x+4*y>=0,["8x + 3y \\le 160","-x + 4y \\ge 0","x \\ge 6"],["8x + 3y \\le 160","-4x + y \\ge 0","x \\ge 6"],">="],
["A shop in Garissa stocks \\(x\\) crates of soda and \\(y\\) cartons of milk.",["The fridge holds at most \\(32\\) crates and cartons altogether.","A crate costs Ksh \\(900\\) and a carton costs Ksh \\(1300\\); the shop can spend at most Ksh \\(31\\,200\\).","There must be at least \\(5\\) cartons of milk."],[1*x+1*y<=32,900*x+1300*y<=31200,1*y>=5],1,"single",1*x<=32,["x \\le 32","900x + 1300y \\le 31\\,200","y \\ge 5"],["x + y \\le 32","900x + 1300y \\le 31\\,200","y \\ge 5"],"<="],
["A farmer in Meru plants \\(x\\) rows of kales and \\(y\\) rows of spinach.",["Each row of kales needs \\(5\\) kg of manure and each row of spinach needs \\(6\\) kg; there are \\(150\\) kg of manure.","There must be more than \\(12\\) rows of kales.","There must be at least \\(5\\) rows of spinach."],[5*x+6*y<=150,1*x>12,1*y>=5],3,"dir",1*y<=5,["5x + 6y \\le 150","x \\gt 12","y \\le 5"],["5x + 6y \\le 150","x \\gt 12","y \\ge 5"],">="],
["A posho mill in Thika grinds \\(x\\) bags of maize and \\(y\\) bags of millet in a day.",["A bag of maize takes \\(9\\) minutes to grind and a bag of millet takes \\(4\\) minutes; the mill runs for at most \\(480\\) minutes.","The mill grinds at least \\(20\\) bags of maize.","The mill grinds more than \\(4\\) bags of millet."],[9*x+4*y<=480,1*x>=20,1*y>4],3,"strict",1*y>=4,["9x + 4y \\le 480","x \\ge 20","y \\ge 4"],["9x + 4y \\le 480","x \\ge 20","y \\gt 4"],">"],
["A county office buys \\(x\\) small water tanks and \\(y\\) large water tanks for a school borehole project.",["A small tank holds \\(2\\) cubic metres and a large tank holds \\(7\\) cubic metres; the tanks must hold at least \\(45\\) cubic metres.","At most \\(12\\) tanks fit on the site.","At most \\(5\\) large tanks are in stock."],[2*x+7*y>=45,1*x+1*y<=12,1*y<=5],1,"dir",2*x+7*y<=45,["2x + 7y \\le 45","x + y \\le 12","y \\le 5"],["2x + 7y \\ge 45","x + y \\le 12","y \\le 5"],">="],
["A uniform maker in Kakamega sews \\(x\\) school shirts and \\(y\\) skirts in a week.",["A shirt takes \\(3\\) hours and a skirt takes \\(7\\) hours; there are \\(100\\) hours of sewing time.","At least \\(6\\) skirts are needed.","The number of shirts must be at least three times the number of skirts."],[3*x+7*y<=100,1*y>=6,1*x-3*y>=0],3,"ratio",3*x-1*y>=0,["3x + 7y \\le 100","y \\ge 6","3x - y \\ge 0"],["3x + 7y \\le 100","y \\ge 6","x - 3y \\ge 0"],">="],
["A honey cooperative in Baringo fills \\(x\\) \\(6\\) kg tins and \\(y\\) \\(1\\) kg jars from \\(300\\) kg of honey.",["The honey in the tins and jars must not be more than the \\(300\\) kg they have.","At least \\(10\\) tins are filled.","Fewer than \\(120\\) tins and jars are filled altogether."],[6*x+1*y<=300,1*x>=10,1*x+1*y<120],1,"swap",1*x+6*y<=300,["x + 6y \\le 300","x \\ge 10","x + y \\lt 120"],["6x + y \\le 300","x \\ge 10","x + y \\lt 120"],"<="]];
ix: 1+rand(10);
E: Q13L[ix];
kk: E[4]; er: E[5];
tk: E[3][kk]; wk: E[6];
keyv: ["i1","i2","i3"][kk];
opts: [["none",false,"None of them: her model is right."],["i1",is(kk=1),"(1)"],["i2",is(kk=2),"(2)"],["i3",is(kk=3),"(3)"]];
wrongi: ["i1","i2","i3"][mod(kk,3)+1];
rl: op(tk);
flip(q) := if op(q) = "<=" then lhs(q) >= rhs(q) elseif op(q) = ">=" then lhs(q) <= rhs(q) elseif op(q) = "<" then lhs(q) > rhs(q) else lhs(q) < rhs(q);
strict(q) := if op(q) = "<=" then lhs(q) < rhs(q) elseif op(q) = ">=" then lhs(q) > rhs(q) elseif op(q) = "<" then lhs(q) <= rhs(q) else lhs(q) >= rhs(q);
tkflip: flip(tk);
tkboth: flip(strict(tk));
/* side or strictness changed, never equal to Wambui's inequality (her error is dir on some entries, strict on others) */
tkone: if er = "dir" then strict(tk) else flip(tk);
tkswap: apply(op(tk), [subst([x=y, y=x], lhs(tk)), rhs(tk)+1]);
incl: if rl = "<=" or rl = ">=" then "include" else "do not include";
sidew: if rl = "<=" or rl = "<" then "\\(\\le\\) or \\(\\lt\\)" else "\\(\\ge\\) or \\(\\gt\\)";
